223		}
224		hist := parseHistoryJSON(t, res.stdout)
225		if hist.Original == nil || hist.Original.Version.ID != "builtin" ||
226			hist.Original.Version.Rules.Displacement.Multiplier != 2 {
227			t.Fatalf("original must be explained under builtin: %+v", hist.Original)
228		}
229		if hist.Original.Finding.Kind != "sandwich" || hist.Original.Finding.Severity != 3 ||
230			len(hist.Original.Finding.Evidence) != 3 {
231			t.Fatalf("legacy conclusion/evidence damaged: %+v", hist.Original.Finding)
232		}
233		if hist.Status != "unreviewed" || hist.Version != 0 {
234			t.Fatalf("legacy default state wrong: %s/%d", hist.Status, hist.Version)
235		}
236		if !strings.Contains(res.stdout, `"revisions":[]`) || !strings.Contains(res.stdout, `"original":{`) {
237			t.Fatalf("legacy history shape wrong: %s", res.stdout)
238		}
239	}
240	
241	// TestCLIReviewsHistorySuccessContent proves a successful history keeps
242	// the current review status and version, every ascending revision, the
243	// original conclusion with its saved detection parameters and the full
244	// swap evidence — for a reviewed object, an unreviewed object and an
245	// identity without a conclusion alike.
246	func TestCLIReviewsHistorySuccessContent(t *testing.T) {
247		dir := setupReviewCLIArchive(t)
248	
249		// Reviewed displacement 0xd: one false-positive revision.
250		res := runCLI(t, "reviews", "history", dir, "1", "0xa", "0xd", "displacement")
251		reviewed := res.stdout
252		if res.exitCode != 0 {
253			t.Fatalf("history failed: %s", res.stderr)
254		}
255		hist := parseHistoryJSON(t, res.stdout)
256		if hist.Status != "false_positive" || hist.Version != 1 || len(hist.Revisions) != 1 {
257			t.Fatalf("review state wrong: %s/%d with %d revisions", hist.Status, hist.Version, len(hist.Revisions))
258		}
259		if hist.Revisions[0]["submissionId"] != "f-1" || hist.Revisions[0]["status"] != "false_positive" {
260			t.Fatalf("revision content wrong: %+v", hist.Revisions[0])
261		}
262		if hist.Original == nil || hist.Original.BlockNumber != 10 ||
263			hist.Original.Finding.TxHash != "0xd" || hist.Original.Finding.Kind != "displacement" ||
264			hist.Original.Finding.Severity != 2 || len(hist.Original.Finding.Evidence) != 2 ||
265			hist.Original.Version.ID != "builtin" {
266			t.Fatalf("original conclusion/evidence/version wrong: %+v", hist.Original)
267		}
268	
269		// Unreviewed sandwich 0xv: defaults plus the full original with its
270		// three-swap evidence; revisions serialize as [].
271		res = runCLI(t, "reviews", "history", dir, "1", "0xa", "0xv", "sandwich")
272		if res.exitCode != 0 {
273			t.Fatalf("unreviewed history failed: %s", res.stderr)
274		}
275		hist = parseHistoryJSON(t, res.stdout)
276		if hist.Status != "unreviewed" || hist.Version != 0 || len(hist.Revisions) != 0 {
277			t.Fatalf("unreviewed state wrong: %s/%d with %d revisions", hist.Status, hist.Version, len(hist.Revisions))
278		}
279		if hist.Original == nil || hist.Original.Finding.Severity != 3 ||
280			len(hist.Original.Finding.Evidence) != 3 {
281			t.Fatalf("unreviewed original wrong: %+v", hist.Original)
282		}
283		if !strings.Contains(res.stdout, `"revisions":[]`) {
284			t.Fatalf("revisions must serialize as []: %s", res.stdout)
285		}
286	
287		// An identity without a conclusion keeps original:null.
288		res = runCLI(t, "reviews", "history", dir, "1", "0xa", "0ghost", "sandwich")
289		if res.exitCode != 0 {
290			t.Fatalf("missing-identity history failed: %s", res.stderr)
291		}
292		hist = parseHistoryJSON(t, res.stdout)
293		if hist.Original != nil || hist.Status != "unreviewed" || hist.Version != 0 {
294			t.Fatalf("missing identity state wrong: %+v", hist)
295		}
296		if !strings.Contains(res.stdout, `"original":null`) {
297			t.Fatalf("missing identity must carry original:null: %s", res.stdout)
298		}
299	
300		// Deterministic output for the reviewed object.
301		again := runCLI(t, "reviews", "history", dir, "1", "0xa", "0xd", "displacement")
302		if again.exitCode != 0 || again.stdout != reviewed {
303			t.Fatalf("history output is not deterministic:\n%s\n%s", reviewed, again.stdout)
304		}
305	}
306	
307	// mustReadFile reads a file or fails the test.
308	func mustReadFile(t *testing.T, path string) []byte {
309		t.Helper()
310		raw, err := os.ReadFile(path)
311		if err != nil {
312			t.Fatal(err)
313		}
