370		if hist.Version != 0 || hist.Status != ReviewStatusUnreviewed || len(hist.Revisions) != 0 {
371			t.Fatalf("rejected duplicate changed review state: %+v", hist)
372		}
373	
374		// The rejected id is not consumed: the complete legal document with the
375		// same id creates version 1 normally.
376		sub, err := ParseReviewSubmission([]byte(good))
377		if err != nil {
378			t.Fatal(err)
379		}
380		res, err := SubmitReview(dir, sub)
381		if err != nil {
382			t.Fatalf("legal resubmit after rejection: %v", err)
383		}
