388		// With the id stored, a duplicate-field resubmission — even one whose
389		// surviving value would match or differ from the stored revision — is
390		// still the parsing failure, not created:false and not a submission-id
391		// conflict.
392		for _, spec := range []string{dupStatus, strings.Replace(dupStatus, `"status":"false_positive"`, `"STATUS":"real"`, 1)} {
