802	// setupReviewCorruptArchive archives the two-findings block (a sandwich
803	// and a displacement hit under builtin) and registers a candidate whose
804	// stored document is about to be damaged: mult3 (multiplier 3) still flags
805	// the displacement 0xd (50 > 30), so the zero-multiplier corruption is one
806	// that previously sent detection into a divide-less but zeroed rule.
807	func setupReviewCorruptArchive(t *testing.T) string {
808		t.Helper()
809		dir := t.TempDir()
810		mustReplay(t, dir, twoFindingsInput)
811		mustRegisterVersion(t, dir, mult3Spec)
812		return dir
