815	// TestEvaluateCorruptVersionRefused runs the same corruption matrix the
816	// single-block comparison enforces against the review-range evaluation:
817	// every damaged candidate document fails the whole evaluation as a corrupt
818	// archived rule version, never as an unknown version, and the message names
819	// the requested version id and the offending rule or field.
820	func TestEvaluateCorruptVersionRefused(t *testing.T) {
821		for _, tc := range corruptVersionCases {
822			t.Run(tc.name, func(t *testing.T) {
823				dir := setupReviewCorruptArchive(t)
824				submit(t, dir, reviewSub("1", "0xa", "0xd", "displacement", "f", "a", "fp", ReviewStatusFalsePositive, 0))
825				rewriteStoredVersion(t, dir, "mult3", func(ver map[string]any) {
826					tc.mutate(t, ver)
827				})
828				_, err := EvaluateReviews(dir, "1", 0, 100, "mult3")
829				if err == nil {
830					t.Fatalf("corrupt version evaluated successfully")
831				}
832				if !errors.Is(err, ErrCorruptVersion) {
833					t.Fatalf("error = %v, want ErrCorruptVersion", err)
834				}
835				if errors.Is(err, ErrUnknownVersion) {
836					t.Fatalf("corruption must not be reported as an unknown version: %v", err)
837				}
838				if !strings.Contains(err.Error(), "mult3") {
