1058	// contenderStatuses gives each racing submitter a status of its own; the
1059	// winner revision can then be proven to carry one submitter's complete
1060	// content with no fields mixed in from another contender.
1061	var contenderStatuses = []string{
1062		ReviewStatusFalsePositive,
1063		ReviewStatusReal,
1064		ReviewStatusUnreviewed,
1065	}
1066	
1067	func raceSub(i int) ReviewSubmission {
1068		return reviewSub("1", "0xa", "0xv", "sandwich",
1069			fmt.Sprintf("race-%02d", i),
1070			fmt.Sprintf("operator-%02d", i),
1071			fmt.Sprintf("reason-%02d", i),
1072			contenderStatuses[i%len(contenderStatuses)], 1)
1073	}
1074	
1075	type raceOutcome struct {
1076		res SubmitReviewResult
1077		err error
1078	}
