1293		}
1294		archiveBefore, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1295		if err != nil {
1296			t.Fatal(err)
1297		}
1298	
1299		holder, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
1300		if err != nil {
1301			t.Fatal(err)
1302		}
1303		if err := syscall.Flock(int(holder.Fd()), syscall.LOCK_EX); err != nil {
1304			t.Fatal(err)
1305		}
1306	
1307		// A legal rejudgment based on version 1: while occupied it must report
1308		// busy and write nothing.
1309		contender := reviewSub("1", "0xa", "0xv", "sandwich", "hold-2", "bob", "second look says false positive", ReviewStatusFalsePositive, 1)
1310		res, err := SubmitReview(dir, contender)
1311		if !errors.Is(err, ErrBusy) {
1312			t.Fatalf("occupied archive: got %v, want ErrBusy", err)
1313		}
1314		if res.Created || res.Version != 0 || res.Revision != (ReviewRevision{}) {
1315			t.Fatalf("busy submission returned a non-empty result: %+v", res)
1316		}
1317		archiveDuring, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1318		if err != nil {
1319			t.Fatal(err)
1320		}
1321		if !reflect.DeepEqual(archiveBefore, archiveDuring) {
1322			t.Fatal("busy submission changed the archive while the lock was held")
1323		}
1324	
1325		// Release the occupation; existing review content must be intact.
1326		if err := syscall.Flock(int(holder.Fd()), syscall.LOCK_UN); err != nil {
1327			t.Fatal(err)
1328		}
1329		if err := holder.Close(); err != nil {
1330			t.Fatal(err)
1331		}
1332		held, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1333		if err != nil {
1334			t.Fatal(err)
1335		}
1336		if held.Status != ReviewStatusReal || held.Version != 1 || len(held.Revisions) != 1 {
1337			t.Fatalf("busy loss altered review content: %+v", held)
1338		}
1339		if !reflect.DeepEqual(held.Revisions[0], first.Revision) {
1340			t.Fatalf("original revision changed: %+v, want %+v", held.Revisions[0], first.Revision)
1341		}
1342	
1343		// Lock released but the object is still at version 1 (busy never
1344		// completed the rejudgment): the same submission with its original
1345		// expectedVersion 1 now succeeds as a fresh create — the busy attempt
1346		// neither consumed the submission id nor counted as a stored revision.
1347		retry, err := SubmitReview(dir, contender)
1348		if err != nil {
1349			t.Fatalf("retry after release: %v", err)
1350		}
1351		wantRev := contender.revision(2)
1352		if !retry.Created || retry.Version != 2 || !reflect.DeepEqual(retry.Revision, wantRev) {
1353			t.Fatalf("retry = %+v, want created at v2 with %+v", retry, wantRev)
1354		}
1355		hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1356		if err != nil {
1357			t.Fatal(err)
1358		}
1359		if hist.Status != ReviewStatusFalsePositive || hist.Version != 2 || len(hist.Revisions) != 2 {
1360			t.Fatalf("object after retry = %q/%d with %d revisions", hist.Status, hist.Version, len(hist.Revisions))
1361		}
1362		if !reflect.DeepEqual(hist.Revisions[0], first.Revision) || !reflect.DeepEqual(hist.Revisions[1], wantRev) {
1363			t.Fatalf("revisions after retry = %+v", hist.Revisions)
1364		}
1365	
1366		// Independently, if another rejudgment had committed while we waited,
1367		// releasing the lock would not make the stale submission succeed: with
1368		// the object now at version 2, a version-1 submission conflicts and
1369		// leaves no revision.
1370		late := reviewSub("1", "0xa", "0xv", "sandwich", "hold-3", "carol", "late arrival", ReviewStatusUnreviewed, 1)
1371		if _, err := SubmitReview(dir, late); !errors.Is(err, ErrReviewConflict) {
1372			t.Fatalf("stale submission after release: got %v, want ErrReviewConflict", err)
1373		}
1374		after, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1375		if err != nil {
1376			t.Fatal(err)
1377		}
1378		if after.Version != 2 || len(after.Revisions) != 2 || !reflect.DeepEqual(after.Revisions, hist.Revisions) {
1379			t.Fatalf("post-release conflict appended a revision: %+v", after)
1380		}
1381	}
