1417	func restoreArchiveSave(t *testing.T, dir string) {
1418		t.Helper()
1419		if err := os.RemoveAll(filepath.Join(dir, archiveFileName+".tmp")); err != nil {
1420			t.Fatalf("restore archive save: %v", err)
1421		}
1422	}
