package mevwatch

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"sync"
	"syscall"
	"testing"
)

// twoFindingsInput (from alerts_test.go) archives block 0xa at height 10
// with a sandwich on 0xv (pool p1, sev 3) and a displacement on 0xd (pool
// p2, sev 2) under the built-in rules.
//
// Candidate versions used below:
//   - strict:       sandwich sev 5 on, displacement mult 5 -> only 0xv keeps
//     hitting, with a changed severity; 0xd stops hitting.
//   - mult3:        displacement mult 3 -> 0xd still hits (50 > 30).
//   - noSandwich:   sandwich off, displacement mult 2 -> 0xv flips from
//     sandwich to displacement (a type change); 0xd stays.
const mult3Spec = `{"id":"mult3","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":3}}}`
const noSandwichSpec = `{"id":"nosandwich","rules":{"sandwich":{"enabled":false,"severity":1},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`

func reviewSub(chain, block, tx, kind, id, operator, reason, status string, expected int) ReviewSubmission {
	return ReviewSubmission{
		ChainID:         chain,
		BlockHash:       block,
		TxHash:          tx,
		Kind:            kind,
		SubmissionID:    id,
		Operator:        operator,
		Reason:          reason,
		Status:          status,
		ExpectedVersion: expected,
	}
}

func submit(t *testing.T, dir string, sub ReviewSubmission) SubmitReviewResult {
	t.Helper()
	res, err := SubmitReview(dir, sub)
	if err != nil {
		t.Fatalf("SubmitReview(%+v): %v", sub, err)
	}
	return res
}

func mustRegisterVersion(t *testing.T, dir, spec string) string {
	t.Helper()
	v, _, err := RegisterVersion(dir, []byte(spec))
	if err != nil {
		t.Fatalf("RegisterVersion: %v", err)
	}
	return v.ID
}

func TestSubmitReviewFirstAndRejudgment(t *testing.T) {
	dir := t.TempDir()
	mustReplay(t, dir, twoFindingsInput)

	first := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-1", "alice", "confirmed bot", ReviewStatusReal, 0))
	if !first.Created || first.Version != 1 || first.Status != ReviewStatusReal {
		t.Fatalf("first submission = %+v", first)
	}
	if first.Revision.Version != 1 || first.Revision.SubmissionID != "s-1" ||
		first.Revision.Operator != "alice" || first.Revision.Reason != "confirmed bot" ||
		first.Revision.ExpectedVersion != 0 {
		t.Fatalf("revision content not preserved: %+v", first.Revision)
	}

	// A stale expected version is a conflict and appends nothing.
	if _, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-2", "bob", "late", ReviewStatusFalsePositive, 0)); !errors.Is(err, ErrReviewConflict) {
		t.Fatalf("stale expectedVersion: got %v, want ErrReviewConflict", err)
	}

	second := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-2", "bob", "actually fp", ReviewStatusFalsePositive, 1))
	if !second.Created || second.Version != 2 || second.Status != ReviewStatusFalsePositive {
		t.Fatalf("second submission = %+v", second)
	}

	// Withdrawal adds another revision and leaves the earlier ones in place.
	withdrawn := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-3", "carol", "reset", ReviewStatusUnreviewed, 2))
	if !withdrawn.Created || withdrawn.Version != 3 || withdrawn.Status != ReviewStatusUnreviewed {
		t.Fatalf("withdrawal = %+v", withdrawn)
	}
}

func TestSubmitReviewIdempotentRetry(t *testing.T) {
	dir := t.TempDir()
	mustReplay(t, dir, twoFindingsInput)

	original := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-1", "alice", "r", ReviewStatusReal, 0))
	// The object is rejudged afterwards.
	submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-2", "bob", "r2", ReviewStatusFalsePositive, 1))

	// Retrying the exact original submission (same ID and identical field
	// values, expectedVersion 0 included) returns the original revision even
	// though the object has since moved on, and appends nothing.
	retry := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-1", "alice", "r", ReviewStatusReal, 0))
	if retry.Created {
		t.Fatalf("identical retry reported created=true")
	}
	if !reflect.DeepEqual(retry.Revision, original.Revision) {
		t.Fatalf("retry returned %+v, want original %+v", retry.Revision, original.Revision)
	}
	if retry.Version != 2 || retry.Status != ReviewStatusFalsePositive {
		t.Fatalf("retry response must reflect current state, got version %d status %q", retry.Version, retry.Status)
	}
	hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
	if err != nil {
		t.Fatal(err)
	}
	if len(hist.Revisions) != 2 {
		t.Fatalf("identical retry appended a revision: %+v", hist.Revisions)
	}
}

func TestSubmitReviewSubmissionIDConflicts(t *testing.T) {
	dir := t.TempDir()
	mustReplay(t, dir, twoFindingsInput)
	submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-1", "alice", "r", ReviewStatusReal, 0))

	// Same ID with different content conflicts, even against another object.
	cases := []ReviewSubmission{
		reviewSub("1", "0xa", "0xv", "sandwich", "s-1", "bob", "r", ReviewStatusReal, 0),
		reviewSub("1", "0xa", "0xv", "sandwich", "s-1", "alice", "other", ReviewStatusReal, 0),
		reviewSub("1", "0xa", "0xv", "sandwich", "s-1", "alice", "r", ReviewStatusFalsePositive, 0),
		reviewSub("1", "0xa", "0xd", "displacement", "s-1", "alice", "r", ReviewStatusReal, 0),
	}
	for i, sub := range cases {
		if _, err := SubmitReview(dir, sub); !errors.Is(err, ErrSubmissionConflict) {
			t.Fatalf("case %d: got %v, want ErrSubmissionConflict", i, err)
		}
	}
	// Failed conflicts must not change stored data.
	hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
	if err != nil {
		t.Fatal(err)
	}
	if hist.Version != 1 || len(hist.Revisions) != 1 {
		t.Fatalf("conflict mutated history: %+v", hist)
	}
}

func TestSubmitReviewUnknownConclusion(t *testing.T) {
	dir := t.TempDir()
	mustReplay(t, dir, twoFindingsInput)
	cases := []ReviewSubmission{
		reviewSub("2", "0xa", "0xv", "sandwich", "s", "a", "r", ReviewStatusReal, 0), // other chain
		reviewSub("1", "0xzzz", "0xv", "sandwich", "s", "a", "r", ReviewStatusReal, 0),
		reviewSub("1", "0xa", "0xnomatch", "sandwich", "s", "a", "r", ReviewStatusReal, 0),
		reviewSub("1", "0xa", "0xd", "sandwich", "s", "a", "r", ReviewStatusReal, 0), // 0xd is displacement
	}
	for i, sub := range cases {
		if _, err := SubmitReview(dir, sub); !errors.Is(err, ErrUnknownConclusion) {
			t.Fatalf("case %d: got %v, want ErrUnknownConclusion", i, err)
		}
	}
}

func TestParseReviewSubmissionValidation(t *testing.T) {
	good := `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"alice","reason":"r","status":"real","expectedVersion":0}`
	sub, err := ParseReviewSubmission([]byte(good))
	if err != nil {
		t.Fatalf("valid spec rejected: %v", err)
	}
	if sub.ExpectedVersion != 0 || sub.Status != ReviewStatusReal {
		t.Fatalf("bad parse: %+v", sub)
	}
	bad := []struct {
		name string
		spec string
	}{
		{"not json", `{"chainId":`},
		{"trailing garbage", good + ` extra`},
		{"missing chain", `{"blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`},
		{"blank block", `{"chainId":"1","blockHash":"  ","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`},
		{"blank tx", `{"chainId":"1","blockHash":"0xa","txHash":"","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`},
		{"unknown kind", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"rugpull","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`},
		{"missing kind", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`},
		{"blank submission id", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"  ","operator":"a","reason":"r","status":"real","expectedVersion":0}`},
		{"blank operator", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"","reason":"r","status":"real","expectedVersion":0}`},
		{"blank reason", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"  ","status":"real","expectedVersion":0}`},
		{"bad status", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"yes","expectedVersion":0}`},
		{"missing status", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","expectedVersion":0}`},
		{"negative expectedVersion", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":-1}`},
		{"missing expectedVersion", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real"}`},
		{"fractional expectedVersion", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":1.5}`},
		{"unknown field", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0,"extra":1}`},
	}
	for _, tc := range bad {
		t.Run(tc.name, func(t *testing.T) {
			if _, err := ParseReviewSubmission([]byte(tc.spec)); err == nil {
				t.Fatal("expected error")
			}
		})
	}
	// The unreviewed status is a valid first submission too.
	withdraw := strings.Replace(good, `"status":"real"`, `"status":"unreviewed"`, 1)
	if _, err := ParseReviewSubmission([]byte(withdraw)); err != nil {
		t.Fatalf("unreviewed status rejected: %v", err)
	}
}

func TestParseReviewSubmissionSingleCompleteObject(t *testing.T) {
	good := `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"alice","reason":"r","status":"real","expectedVersion":0}`
	// Leading/trailing spaces, tabs and newlines are fine.
	if _, err := ParseReviewSubmission([]byte(" \n\t" + good + "\t\n ")); err != nil {
		t.Fatalf("whitespace-padded spec rejected: %v", err)
	}
	// Brackets inside string values are field content, never object
	// boundaries or trailing data.
	bracketsInString := strings.Replace(good, `"reason":"r"`, `"reason":"weird } ] { ["`, 1)
	sub, err := ParseReviewSubmission([]byte(bracketsInString))
	if err != nil {
		t.Fatalf("brackets inside a string rejected: %v", err)
	}
	if sub.Reason != "weird } ] { [" {
		t.Fatalf("string value not preserved verbatim: %q", sub.Reason)
	}
	bad := []struct {
		name string
		spec string
		want string // substring the error must carry (syntax failures only need non-nil)
	}{
		{"empty", ``, "empty input"},
		{"whitespace only", "  \n\t\r ", "empty input"},
		{"array", `[]`, "array"},
		{"array of object", `[` + good + `]`, "array"},
		{"null", `null`, "null"},
		{"scalar", `7`, ""},
		{"boolean", `true`, ""},
		{"string", `"x"`, ""},
		{"incomplete object", `{"chainId":"1"`, "invalid review spec"},
		{"extra closing brace", good + `}`, "trailing"},
		{"extra closing bracket", good + `]`, "trailing"},
		{"second object", good + ` ` + good, "trailing"},
		{"trailing value", good + ` 7`, "trailing"},
		{"trailing null", good + ` null`, "trailing"},
		{"trailing array", good + ` []`, "trailing"},
		{"trailing text", good + ` extra`, "trailing"},
		{"trailing brace no space", good + `}}`, "trailing"},
	}
	for _, tc := range bad {
		t.Run(tc.name, func(t *testing.T) {
			_, err := ParseReviewSubmission([]byte(tc.spec))
			if err == nil {
				t.Fatal("expected error")
			}
			if tc.want != "" && !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("error %q does not mention %q", err.Error(), tc.want)
			}
		})
	}
}

// TestParseReviewSubmissionTrailingBracketsNameToken pins that stray
// brackets after the object are reported as trailing content naming the
// token, not as a generic syntax error, a version conflict or anything
// business related.
func TestParseReviewSubmissionTrailingBracketsNameToken(t *testing.T) {
	good := `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"alice","reason":"r","status":"real","expectedVersion":0}`
	for _, tc := range []struct {
		suffix string
		token  string
	}{
		{`}`, "closing brace"},
		{`]`, "closing bracket"},
		{` {"x":1}`, "object"},
		{`[1]`, "array"},
		{`"x"`, "string"},
	} {
		_, err := ParseReviewSubmission([]byte(good + tc.suffix))
		if !errors.Is(err, ErrReviewTrailingData) {
			t.Fatalf("suffix %q: got %v, want ErrReviewTrailingData", tc.suffix, err)
		}
		if !strings.Contains(err.Error(), tc.token) {
			t.Fatalf("suffix %q: error %q must name %s", tc.suffix, err.Error(), tc.token)
		}
	}
}

// TestParseReviewSubmissionDuplicateField pins that declaring any supported
// field twice rejects the whole document — under any spellings the decoder
// folds together, with identical values, and with one side null — instead
// of letting the later value silently override the earlier one.
func TestParseReviewSubmissionDuplicateField(t *testing.T) {
	good := `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"alice","reason":"r","status":"real","expectedVersion":0}`
	dup := []struct {
		name  string
		spec  string
		field string // canonical field name the error must carry
	}{
		{"status twice", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","status":"false_positive","expectedVersion":0}`, "status"},
		{"status identical values", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","status":"real","expectedVersion":0}`, "status"},
		{"status null then value", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":null,"status":"real","expectedVersion":0}`, "status"},
		{"status value then null", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","status":null,"expectedVersion":0}`, "status"},
		{"status case folded", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","STATUS":"real","expectedVersion":0}`, "status"},
		{"status escaped spelling", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","sta\u0074us":"real","expectedVersion":0}`, "status"},
		{"expectedVersion twice", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0,"expectedVersion":7}`, "expectedVersion"},
		{"expectedVersion identical", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0,"expectedVersion":0}`, "expectedVersion"},
		{"expectedVersion null then value", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":null,"expectedVersion":0}`, "expectedVersion"},
		{"chainId twice", `{"chainId":"1","chainId":"2","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`, "chainId"},
		{"blockHash twice", `{"chainId":"1","blockHash":"0xa","blockHash":"0xb","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`, "blockHash"},
		{"txHash twice", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","txHash":"0xw","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`, "txHash"},
		{"kind twice", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","kind":"displacement","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`, "kind"},
		{"submissionId twice", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","submissionId":"t","operator":"a","reason":"r","status":"real","expectedVersion":0}`, "submissionId"},
		{"operator twice", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","operator":"b","reason":"r","status":"real","expectedVersion":0}`, "operator"},
		{"reason twice", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"s","operator":"a","reason":"r","reason":"q","status":"real","expectedVersion":0}`, "reason"},
		{"kind case folded", `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","Kind":"sandwich","submissionId":"s","operator":"a","reason":"r","status":"real","expectedVersion":0}`, "kind"},
	}
	for _, tc := range dup {
		t.Run(tc.name, func(t *testing.T) {
			_, err := ParseReviewSubmission([]byte(tc.spec))
			if err == nil {
				t.Fatal("duplicate field parsed")
			}
			if !strings.Contains(err.Error(), "duplicate") || !strings.Contains(err.Error(), `"`+tc.field+`"`) {
				t.Fatalf("error %q does not name the duplicate field %q", err, tc.field)
			}
			if strings.Contains(err.Error(), "trailing") {
				t.Fatalf("duplicate reported as trailing data: %q", err)
			}
		})
	}

	// A field name or brackets inside a string value is content, never a
	// second declaration.
	reasonMentionsField := strings.Replace(good, `"reason":"r"`, `"reason":"status says {\"status\":\"real\"} ]"`, 1)
	sub, err := ParseReviewSubmission([]byte(reasonMentionsField))
	if err != nil {
		t.Fatalf("field name inside reason rejected: %v", err)
	}
	if sub.Reason != `status says {"status":"real"} ]` {
		t.Fatalf("reason not preserved verbatim: %q", sub.Reason)
	}

	// A single declaration under a folded or escaped supported spelling is
	// still a legal document.
	folded := strings.Replace(good, `"status":"real"`, `"STATUS":"real"`, 1)
	if sub, err := ParseReviewSubmission([]byte(folded)); err != nil || sub.Status != ReviewStatusReal {
		t.Fatalf("single folded spelling: sub=%+v err=%v", sub, err)
	}
}

// TestSubmitReviewDuplicateFieldChangesNothing proves the duplicate-field
// failure happens entirely in parsing, before any archive state is touched:
// no revision is appended, no version moves, and the submission id stays
// free — even when that id already names a stored legal submission, the
// ambiguous document is an input error, never the idempotent created:false
// retry and never a submission-id conflict.
func TestSubmitReviewDuplicateFieldChangesNothing(t *testing.T) {
	dir := t.TempDir()
	mustReplay(t, dir, twoFindingsInput)
	good := `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"r-1","operator":"alice","reason":"r","status":"real","expectedVersion":0}`
	dupStatus := `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"r-1","operator":"alice","reason":"r","status":"real","status":"false_positive","expectedVersion":0}`

	if _, err := ParseReviewSubmission([]byte(dupStatus)); err == nil {
		t.Fatal("duplicate-field spec parsed")
	}
	hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
	if err != nil {
		t.Fatal(err)
	}
	if hist.Version != 0 || hist.Status != ReviewStatusUnreviewed || len(hist.Revisions) != 0 {
		t.Fatalf("rejected duplicate changed review state: %+v", hist)
	}

	// The rejected id is not consumed: the complete legal document with the
	// same id creates version 1 normally.
	sub, err := ParseReviewSubmission([]byte(good))
	if err != nil {
		t.Fatal(err)
	}
	res, err := SubmitReview(dir, sub)
	if err != nil {
		t.Fatalf("legal resubmit after rejection: %v", err)
	}
	if !res.Created || res.Version != 1 {
		t.Fatalf("legal resubmit = %+v, want created at version 1", res)
	}

	// With the id stored, a duplicate-field resubmission — even one whose
	// surviving value would match or differ from the stored revision — is
	// still the parsing failure, not created:false and not a submission-id
	// conflict.
	for _, spec := range []string{dupStatus, strings.Replace(dupStatus, `"status":"false_positive"`, `"STATUS":"real"`, 1)} {
		if _, err := ParseReviewSubmission([]byte(spec)); err == nil {
			t.Fatalf("duplicate-field reuse of stored id parsed: %s", spec)
		} else if errors.Is(err, ErrSubmissionConflict) {
			t.Fatalf("duplicate-field reuse reported as submission conflict: %v", err)
		}
	}
	hist, err = ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
	if err != nil {
		t.Fatal(err)
	}
	if hist.Version != 1 || len(hist.Revisions) != 1 {
		t.Fatalf("duplicate-field reuse mutated history: %+v", hist)
	}
}

// TestSubmitReviewCorruptSpecChangesNothing proves the trailing-data
// failure happens entirely in parsing, before any archive state is touched:
// no revision is appended, no version moves, and the submission id stays
// free for a later complete, legal document.
func TestSubmitReviewCorruptSpecChangesNothing(t *testing.T) {
	dir := t.TempDir()
	mustReplay(t, dir, twoFindingsInput)
	good := `{"chainId":"1","blockHash":"0xa","txHash":"0xv","kind":"sandwich","submissionId":"r-1","operator":"alice","reason":"r","status":"real","expectedVersion":0}`

	for _, suffix := range []string{`}`, `]`, ` ` + good, ` x`} {
		if _, err := ParseReviewSubmission([]byte(good + suffix)); err == nil {
			t.Fatalf("corrupt spec %q parsed", suffix)
		}
	}
	hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
	if err != nil {
		t.Fatal(err)
	}
	if hist.Version != 0 || hist.Status != ReviewStatusUnreviewed || len(hist.Revisions) != 0 {
		t.Fatalf("rejected inputs changed review state: %+v", hist)
	}

	// The rejected id is not consumed: the complete legal document with the
	// same id creates version 1 normally.
	sub, err := ParseReviewSubmission([]byte(good))
	if err != nil {
		t.Fatal(err)
	}
	res, err := SubmitReview(dir, sub)
	if err != nil {
		t.Fatalf("legal resubmit after rejection: %v", err)
	}
	if !res.Created || res.Version != 1 {
		t.Fatalf("legal resubmit = %+v, want created at version 1", res)
	}

	// Reusing a stored id with a structurally corrupt document still fails
	// parsing: it must never come back as the idempotent created:false retry.
	for _, suffix := range []string{`}`, `]`, ` ` + good} {
